    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    dangerous_prev = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('budget', 0) > 0:
                    dangerous_prev.append(float(bid))

    if not alive_opponents:
        return float(min(budget, 10.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    active_high = max(dangerous_prev) if dangerous_prev else 0.0

    competitors = 1
    for opp in alive_opponents:
        if opp.get('budget', 0) > 0 and opp.get('hp', 0) > -5:
            competitors += 1

    req_units = int(supply // WATER_REQ)
    scarcity = req_units < competitors
    very_tight = req_units <= 1

    need_score = 0
    if hp <= 2:
        need_score += 4
    elif hp <= 4:
        need_score += 3
    elif hp <= 6:
        need_score += 2
    else:
        need_score += 1

    if no_water_days >= 2:
        need_score += 3
    elif no_water_days >= 1:
        need_score += 1

    if scarcity:
        need_score += 2
    if very_tight:
        need_score += 1

    target = 0.0

    if active_high > 300:
        active_high = 155.0

    if need_score >= 7:
        target = max(150.5, active_high + 2.5)
    elif need_score >= 5:
        target = max(148.0, active_high + 1.5)
    elif need_score >= 3:
        if active_high >= 145:
            target = 146.0
        else:
            target = max(92.0, active_high * 0.72 + 8.0)
    else:
        if highest_prev >= 145:
            target = 58.0
        else:
            target = max(28.0, active_high * 0.38 + 6.0)

    if budget < 80 and need_score < 5:
        target = min(target, 55.0)
    if budget < 40:
        if need_score >= 6:
            target = budget
        else:
            target = min(target, 22.0)

    if hp <= 1 or no_water_days >= 3:
        target = max(target, active_high + 3.0, 155.0)

    target = min(target, budget)
    if target < 0:
        target = 0.0
    return float(target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids to infer pressure.
    prev_bids = []
    prev_by_opp = {}
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                bf = float(b)
                prev_bids.append(bf)
                prev_by_opp[oid] = bf
            except Exception:
                pass

    # Determine competitive tier.
    if prev_bids:
        max_prev = max(prev_bids)
        # If someone bid extremely high yesterday, assume they will keep bidding high.
        # We aim for a mid-high bid to avoid being starved, but not match max.
        if max_prev >= 300:
            base = DAILY_SALARY * 0.65
        elif max_prev >= 120:
            base = DAILY_SALARY * 0.55
        else:
            base = DAILY_SALARY * 0.45
    else:
        base = DAILY_SALARY * 0.45

    # Urgency adjustment based on our hp and no-water streak.
    # If we have been without water, raise bids sharply.
    if no_water_days >= 2 or hp <= 2:
        base *= 1.35
    elif no_water_days == 1 or hp <= 4:
        base *= 1.15

    # Supply-based adjustment: when supply is low, competition likely increases.
    if supply <= float(WATER_REQ):
        base *= 1.15
    elif supply >= 0.9 * float(MAX_SUPPLY):
        base *= 0.95

    # Cap by budget and keep within a reasonable band.
    bid = min(budget, base)

    # If budget is too low, bid what we can to avoid death.
    if bid < 1e-6:
        bid = min(budget, DAILY_SALARY * 0.2)

    # Final safety clamp.
    if bid < 0.0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents are alive, bid a minimal amount to conserve budget.
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    # Collect yesterday's bids from all alive opponents.
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Determine base bid strategy based on my current health and water status.
    my_target_bid = 0.0

    # If HP is critical (2 or less) or I've gone without water, bid very aggressively.
    if my_status['hp'] <= 2 or my_status['no_water_days'] > 0:
        my_target_bid = DAILY_SALARY * 0.95 # Highly aggressive bid (e.g., 142.5)
    else:
        # If HP is stable, bid competitively but with some budget consideration.
        my_target_bid = DAILY_SALARY * 0.75 # Moderately aggressive bid (e.g., 112.5)

    # Adjust bid based on yesterday's highest opponent bid to ensure competitive edge.
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if my_status['hp'] <= 2 or my_status['no_water_days'] > 0:
            # When desperate, ensure to outbid the highest previous bid with a good margin.
            my_target_bid = max(my_target_bid, highest_prev_bid + 5.0)
        else:
            # When stable, aim to outbid, but be slightly more cautious if bids were extremely high.
            if highest_prev_bid >= DAILY_SALARY * 0.9:
                my_target_bid = max(my_target_bid, highest_prev_bid + 1.0) # Just edge them out
            else:
                my_target_bid = max(my_target_bid, highest_prev_bid + 2.5) # A small increment

    # Consider the day in the meta-round for end-game aggressiveness.
    # If it's near the end and I have a healthy budget, I can afford to be more aggressive.
    if day_context['day'] >= EPISODE_DAYS - 2 and my_status['budget'] > DAILY_SALARY:
        my_target_bid = max(my_target_bid, DAILY_SALARY * 1.0) # Bid full salary if needed

    # Ensure the final bid does not exceed the current budget.
    final_bid = min(my_status['budget'], my_target_bid)

    # Ensure a minimum bid if I need water (not full HP) to prevent bidding too low by mistake.
    if my_status['hp'] < 10 and final_bid < DAILY_SALARY * 0.2:
        final_bid = max(final_bid, DAILY_SALARY * 0.2) # Set a floor of 30 if not full HP

    return final_bid

